  /** The names of the person's patrons, sorted, comma and space separated. */
  protected patronNames(person: PersonView): string {
    const nameOf = new Map(this.people().map((p) => [p.id, p.name]));
    return person.patronIds.map((id) => nameOf.get(id) ?? '').filter((n) => n !== '')
      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)).join(', ');
  }

  /** The person's backing: their patrons' settled figures added up, over their SETTLED claims dated
   *  within the 90 days up to and including the sheet's today, each at its frozen figure; 0.00 with none. */
  protected backing(person: PersonView): string {
    const today = this.session.sheet()?.today;
    if (today === undefined) return money(0);
    const from = daysBefore(today, 89);
    const patrons = new Set(person.patronIds);
    let total = 0;
    for (const c of this.claims()) {
      if (patrons.has(c.personId) && c.status === 'SETTLED' && c.settledDue !== null
        && c.date >= from && c.date <= today) total += cents(c.settledDue);
    }
    return money(total);
  }

